#pragma once

#include <QString>

struct Preferences
{
    int fontSize = 12;
    QString lastDir;

    static Preferences load();
    void save() const;
};

#include "preferences.h"

#include <QDir>
#include <QFile>
#include <QStringList>
#include <QTextStream>

static QString configPath()
{
    return QDir::homePath() + "/.notepad.conf";
}

Preferences Preferences::load()
{
    Preferences prefs;
    QFile file(configPath());
    if (!file.open(QIODevice::ReadOnly | QIODevice::Text))
        return prefs;
    QTextStream in(&file);
    while (!in.atEnd()) {
        const QStringList parts = in.readLine().split('=');
        if (parts.size() != 2)
            continue;
        if (parts[0] == "fontSize")
            prefs.fontSize = parts[1].toInt();
        else if (parts[0] == "lastDir")
            prefs.lastDir = parts[1];
    }
    return prefs;
}

void Preferences::save() const
{
    QFile file(configPath());
    if (!file.open(QIODevice::WriteOnly | QIODevice::Text))
        return;
    QTextStream out(&file);
    out << "fontSize=" << fontSize << "\n";
    out << "lastDir=" << lastDir << "\n";
}

#include <QApplication>

#include "mainwindow.h"

int main(int argc, char *argv[])
{
    QApplication app(argc, argv);

    MainWindow window;
    window.show();
    return app.exec();
}

