#include "preferences.h"

#include <QDir>
#include <QSettings>

Preferences Preferences::load()
{
    QSettings settings;
    Preferences prefs;
    prefs.fontSize = settings.value("editor/fontSize", 12).toInt();
    prefs.lastDir = settings.value("files/lastDir", QDir::homePath()).toString();
    return prefs;
}

void Preferences::save() const
{
    QSettings settings;
    settings.setValue("editor/fontSize", fontSize);
    settings.setValue("files/lastDir", lastDir);
}

int main(int argc, char *argv[])
{
    QApplication app(argc, argv);
    QCoreApplication::setOrganizationName("Acme");
    QCoreApplication::setApplicationName("Notepad");

    MainWindow window;
    window.show();
    return app.exec();
}

MainWindow::MainWindow(QWidget *parent)
    : QMainWindow(parent)
{
    QSettings settings;
    restoreGeometry(settings.value("window/geometry").toByteArray());
}

void MainWindow::closeEvent(QCloseEvent *event)
{
    QSettings settings;
    settings.setValue("window/geometry", saveGeometry());
    QMainWindow::closeEvent(event);
}
